import java.util.Map;
final class TemplateMath {
 static long eval(String s, Map<String,Long> v){ return new P(s,v).expr(); }
 static final class P{final String s;final Map<String,Long>v;int i;P(String s,Map<String,Long>v){this.s=s;this.v=v;}void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}long expr(){long x=term();for(;;){ws();if(i>=s.length())return x;char c=s.charAt(i);if(c!='+'&&c!='-')return x;i++;long y=term();x=c=='+'?x+y:x-y;}}long term(){long x=factor();for(;;){ws();if(i>=s.length())return x;char c=s.charAt(i);if(c!='*'&&c!='/'&&c!='%')return x;i++;long y=factor();x=c=='*'?x*y:c=='/'?(y==0?0:x/y):(y==0?0:x%y);}}long factor(){ws();if(i<s.length()&&s.charAt(i)=='-'){i++;return-factor();}if(i<s.length()&&s.charAt(i)=='('){i++;long x=expr();ws();if(i<s.length()&&s.charAt(i)==')')i++;return x;}int a=i;while(i<s.length()&&(Character.isLetterOrDigit(s.charAt(i))||s.charAt(i)=='_'||s.charAt(i)=='.'))i++;String n=s.substring(a,i);ws();if(i<s.length()&&s.charAt(i)=='('){i++;long x=expr();ws();long y=0;if(i<s.length()&&s.charAt(i)==','){i++;y=expr();}ws();if(i<s.length()&&s.charAt(i)==')')i++;if("min".equals(n))return Math.min(x,y);if("max".equals(n))return Math.max(x,y);if("ceildiv".equals(n))return y==0?0:(x+y-1)/y;throw new IllegalArgumentException("Unknown math function "+n);}if(n.matches("\\d+"))return Long.parseLong(n);Long x=v.get(n);if(x==null)throw new IllegalArgumentException("Unknown math variable "+n+" in "+s);return x;}}
}
